    {"id": "quest-machiko-living-statue", "kind": "quest", "game": "dqm1", "campaigns": ["terry"], "title": "Claim Machiko’s Living Statue", "region": "GreatTree", "summary": "Win Class A in the GreatTree arena to receive a monster that already knows Puff-puff.", "details": ["Defeat Machiko in the Class A final, then talk to her in the GreatTree Tavern.", "Accept her offer with an open spot at the farm. She sends the Living Statue there. If the farm is full, make room and speak to her again."], "spoiler": "story", "related": ["story-terry-collection", "npc-machiko", "quest-arena-dqm1-a"], "species_ids": [249], "source_ids": ["s0adf7000_d66e", "s0adf7000_d6eb", "s0adf7000_d73b", "s0adf7000_d7a6"], "quest_group": "Hidden gates and favors", "quest_order": 5, "map_ids": ["map-11-4", "map-10-0"]},
    {"id": "quest-mermaid-sailor-ring", "kind": "quest", "game": "dqm2", "campaigns": ["cobi", "tara"], "title": "Collect the Sailor Ring", "region": "Water World", "summary": "Once the Ghost Ship disappears, the queen of the mermaids has a reward for you.", "details": ["Return to the Mermaid Kingdom and speak to the queen after retrieving the Moonstone from the pirates.", "Leave one space in your inventory for the Sailor Ring. If your bag is full, the queen keeps it until you return."], "spoiler": "story", "related": ["story-pirate-mermaids", "npc-queen-of-the-mermaids", "quest-recover-the-moonstone"], "species_ids": [], "source_ids": ["s0049f000_1549", "s0049f000_158f", "s0049f000_1602", "s0049f000_161b", "s0049f000_1666"], "quest_group": "Optional quests", "quest_order": 1, "map_ids": ["map-25-2"]},
    {"id": "quest-greatlog-spirit-recruits", "kind": "quest", "game": "dqm2", "campaigns": ["cobi", "tara"], "title": "Choose Petitbou or Warubou", "region": "GreatLog", "summary": "After saving GreatLog, the number of species in your encyclopedia determines which spirit offers to join.", "details": ["Visit Warubou at GreatLog’s Navel with room on the farm. With 250–289 registered species and neither spirit claimed, he asks you to take Petitbou.", "For Warubou himself, decline Petitbou’s offer. Return with at least 290 registered species and Warubou offers to travel with you.", "Accept the companion you want. Accepting either closes the other offer on this save."], "spoiler": "ending", "related": ["story-greatlog-spirit-rewards", "npc-warubou", "npc-petitbou", "npc-greatlog-librarian"], "species_ids": [], "source_ids": ["s003b7800_25a0", "s003b7800_25fa", "s003b7800_264d", "s003b7800_2764", "s003b7800_27ff", "s003b7800_2872", "s003b7800_289d", "s003b7800_291c"], "quest_group": "Postgame", "quest_order": 2, "map_ids": ["map-16-7"]},
    {"id": "quest-free-the-king-of-northden", "kind": "quest", "game": "dqm2", "campaigns": ["cobi", "tara"], "title": "Free Northden’s king", "region": "Ice World", "summary": "The Spirit Mark gets you into Northden Castle. The prisoner in its dungeon can help you expose the false king.", "details": ["Examine the shield at the Spirit’s Spring west of Northden. Agree to help the spirit and leave space in your inventory for the Spirit Mark.", "Show the mark at Northden Castle. In the dungeon, speak to the prisoner and examine the weak wall. Use your rock-breaking power to escape.", "Return to the throne room and defeat the impostor. Rest, then take the route through Nofo to Westernia."], "spoiler": "story", "related": ["story-ice-northden", "npc-king-of-northden", "boss-northden-impostor"], "species_ids": [], "source_ids": ["s004d6000_0026", "s004d6000_0222", "s0044a800_031a", "s0044a800_1af6", "s0044a800_2e68", "s0044a800_2f3b", "s0044a800_2fe0", "s0044a800_314c", "s0044a800_1ea3", "s0044a800_235c"], "quest_group": "Story quests", "quest_order": 8, "map_ids": ["map-36-0", "map-34-2", "map-34-3"]},
    {"id": "quest-ugors-transform-staff", "kind": "quest", "game": "dqm2", "campaigns": ["cobi", "tara"], "title": "Find Ugor’s Transform Staff", "region": "Sky World", "summary": "The villagers at Funt can tell you why the Sage’s Tower turned your party away.", "details": ["Take tame monsters to the Sage’s Tower. The tower checks your companions’ wildness before it will let you in.", "Examine Ugor’s grave and agree to find the missing orb. Search the hollow behind the grave for the Transform Staff.", "Use the staff to disguise yourself at the rope bridge south of Funt. In Pei, ask about the bird attracted to shiny monsters and investigate its nest on the Western Mountain."], "spoiler": "story", "related": ["story-sky-ugor"], "species_ids": [], "source_ids": ["s0031d800_002e", "s0031d800_0085", "s0031d800_0613", "s0031d800_00db", "s0031d800_024b", "s0031d800_02a0", "s0031d800_03dd", "s0031d800_03f9", "s0031d800_092f", "s0028f000_006a", "s0047e000_042c", "s0047e000_04a3"], "quest_group": "Story quests", "quest_order": 11, "map_ids": ["map-46-0", "map-41-0", "map-50-0"]},
    {"id": "quest-sky-dragon-egg", "kind": "quest", "game": "dqm1", "campaigns": ["terry"], "title": "Catch the Sky Dragon egg", "region": "GreatTree", "summary": "Pulio’s hint about the dragon above the Monster Farm leads to a free egg.", "details": ["After unlocking breeding, return to the Monster Farm and examine the “Watch overhead!” sign beneath the flying Sky Dragon. Check the sign again if Terry gets hit by droppings.", "Keep one space open at the farm. Pulio holds the egg for you when it lands. If the farm is full, make room and return.", "Visit the Monster Elder at the Starry Shrine to hatch the egg."], "spoiler": "story", "related": ["npc-pulio", "npc-monster-elder", "story-terry-collection"], "map_ids": ["map-10-0", "map-6-13"], "species_ids": [52], "source_ids": ["s0b113000_0aaf", "s0b113000_0892", "s0b113000_08a9", "s0b113000_08d6", "s0b113000_0927", "s0ab53000_35b5", "s0b113000_00ee"], "quest_group": "Hidden gates and favors", "quest_order": 7},
    {"id": "quest-medal-gate", "kind": "quest", "game": "dqm1", "campaigns": ["terry"], "title": "Open the Medal Gate", "region": "GreatTree", "summary": "Turn in 13 Tiny Medals to open another gate in the Medal Man’s Room.", "details": ["Take the Tiny Medals you find to the Medal Man in GreatTree. After turning in 13, talk to the other medal fan in his room.", "Leave and come back. The companion has found the hidden Travelers’ Gate and will let you through."], "spoiler": "story", "related": ["npc-medal-man", "field-medals", "item-44", "story-terry-optional-gates"], "map_ids": ["map-6-3"], "species_ids": [], "source_ids": ["s0ab53000_59ee", "s0ab53000_5ad2", "s0ab53000_5b43", "s0ab53000_5b6c", "s0ab53000_5b8c", "s0ab53000_5bb2", "s0ab53000_5bd8", "m_exe_08f058"], "quest_group": "Hidden gates and favors", "quest_order": 8},
    {"id": "quest-talking-pot-key", "kind": "quest", "game": "dqm2", "campaigns": ["cobi", "tara"], "title": "Trade a Tiny Medal for the pot’s key", "region": "GreatLog", "summary": "A talking pot on GreatLog’s Main Street offers a one-time magic key.", "details": ["Once you can cross water, reach the pot by the well on Main Street and put a Tiny Medal inside.", "Return after saving GreatLog to collect the magic key. Leave space on the key ring. The pot gives only one key. Take further medals to the Medal Collector."], "spoiler": "story", "related": ["npc-medal-collector", "field-medals", "item-44"], "map_ids": ["map-13-0", "map-12-14"], "species_ids": [], "source_ids": ["s00419800_0050", "s00419800_0072", "s00419800_0142", "s00419800_0197", "s00419800_0345", "s00419800_0372", "s003f6800_2963"], "quest_group": "Optional quests", "quest_order": 3}
